import sys

def main():
    lines = []
    for line in sys.stdin:
        lines.append(line.rstrip('\n'))

    if len(lines) < 3:
        return

    try:
        vault_id = int(lines[0])
        password = lines[1]
        input_password = lines[2]
    except (ValueError, IndexError):
        print("Audit Failed")
        return

    if input_password == password and len(password) > 0:
        print(f"Vault {vault_id} Audit Successful")
    else:
        print("Audit Failed")

if __name__ == "__main__":
    main()
